#!/usr/bin/env node
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { setTimeout as sleep } from "node:timers/promises";

const [agent, promptFile] = process.argv.slice(2);
const prompt = promptFile ? readFileSync(promptFile, "utf8") : "";
const record = process.env.SOCIOTECHNIC_RECORD;
const worktree = process.env.SOCIOTECHNIC_WORKTREE;
const round = process.env.SOCIOTECHNIC_ROUND ?? "0";
const dispatch = process.env.SOCIOTECHNIC_DISPATCH ?? "d-000";

const releaseFile = process.env.SOCIOTECHNIC_FAKE_RELEASE_FILE;
while (releaseFile && !existsSync(releaseFile)) await sleep(10);

const sleepMs = Number(process.env.SOCIOTECHNIC_FAKE_SLEEP_MS ?? "0");
if (sleepMs > 0) await sleep(sleepMs);
if (process.env.SOCIOTECHNIC_FAKE_FAIL === agent) {
  process.stderr.write(`fake ${agent} failing on purpose\n`);
  process.exit(1);
}

function git(...args) {
  return execFileSync(
    "git",
    ["-c", "user.name=sociotechnic-fake", "-c", "user.email=fake@example.invalid", "-c", "commit.gpgsign=false", "-c", "core.hooksPath=/dev/null", ...args],
    { cwd: worktree, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
  ).trim();
}

function write(text) {
  mkdirSync(dirname(record), { recursive: true });
  writeFileSync(record, text);
}

const plan = {
  title: "Add the feature file",
  summary: "Adds a feature file under src so the driver test can run a full round.",
  tier: "EASY",
  tierReason: "One new file following no new pattern.",
  stages: [{ id: "s1", title: "Feature file", description: "Write src/feature.txt.", files: ["src/feature.txt"], acceptance: ["src/feature.txt exists"], risks: [] }],
  acceptance: ["src/feature.txt exists"],
  touches: ["src/**"],
  docsImpact: { required: false, files: [], note: "none" },
  testing: { strategy: "none needed", cases: ["file exists"] },
  risks: [],
  outOfScope: [],
};

if (agent === "sociotechnic-planner") {
  const approvedDigest = /Required plan\.designDigest: (sha256:[0-9a-f]{64})/.exec(prompt)?.[1];
  if (approvedDigest) plan.designDigest = approvedDigest;
  if (prompt.includes("AUTO_DESIGN_FIXTURE") && !approvedDigest) write(JSON.stringify({ status: "needs-design", reason: "Fixture requests a major UI redesign" }));
  else write(JSON.stringify(plan, null, 2));
 } else if (agent === "sociotechnic-designer") {
  const phase = /Current phase: (interview|directions|previews)/.exec(prompt)?.[1];
  const iteration = /round-([0-9]+)\.json$/.exec(record)?.[1];
  const title = phase === "interview" ? "Understand the product" : phase === "directions" ? "Choose a design direction" : "Approve a composition";
  const steering = /Current human revision note: ([^\n]+)/.exec(prompt)?.[1];
  const packet = { phase, title, strategy: "Automated fixture preview. These alternatives exercise the ceremony; they were not generated by a live Fable model." + (steering && steering !== "none" ? `\n\nRevision: ${steering}` : ""), product: phase === "interview" ? "" : "# Product\nA local research notebook for practitioners.\n" };
  if (phase === "interview") packet.questions = [{ id: "audience", prompt: "Who uses this, and what must they accomplish?" }];
  else {
    mkdirSync(process.env.SOCIOTECHNIC_DESIGN_ARTIFACTS, { recursive: true });
    packet.options = ["Research desk", "Reading room", "Working ledger"].map((name, i) => {
      const file = `option-${i + 1}.html`;
      const backgrounds = ["#f1f5f9", "#fff9ef", "#152438"];
      const foregrounds = ["#182337", "#352a1b", "#f1f5f9"];
      const content = `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${name}</title><style>body{margin:0;padding:32px;background:${backgrounds[i]};color:${foregrounds[i]};font:16px/1.6 system-ui}h1{font-size:36px;line-height:1.1}main{max-width:900px;margin:auto}nav{border-bottom:1px solid currentColor;padding-bottom:12px}section{display:grid;grid-template-columns:${i === 0 ? "1fr 2fr" : i === 1 ? "1fr" : "2fr 1fr"};gap:24px}article{border-top:1px solid currentColor;padding-top:16px}small{font-size:12px}button{padding:12px 18px;border:1px solid currentColor;background:transparent;color:inherit;border-radius:6px}</style><main><nav>Field notes · Notebook · Sources</nav><h1>${name}</h1><p>Keep your research, evidence and next questions together.</p><section><article><h2>Recent notes</h2><p>Witness chronology</p><p>Questions for review</p><p>Source collection</p></article><article><h2>Prepare the next conversation</h2><p>Read the record, note what remains uncertain, and connect each observation to its source.</p><button type="button">Create a note</button><p><small>Static prototype · automated test fixture</small></p></article></section></main></html>`;
      writeFileSync(join(process.env.SOCIOTECHNIC_DESIGN_ARTIFACTS, file), content);
      return { id: `option-${i + 1}`, title: name, thesis: ["A workspace centered on the current research task.", "A reading-first composition with quiet supporting controls.", "A dense working view for comparing evidence."][i], rationale: "Organize the real work before selecting decorative details.", risk: "The final product needs responsive and keyboard verification.", preview: `design/atelier/round-${iteration}/${file}` };
    });
  }
  mkdirSync(dirname(process.env.SOCIOTECHNIC_DESIGN_RECEIPT), { recursive: true });
  if (!prompt.includes("MISSING_DESIGN_CONTEXT_FIXTURE")) writeFileSync(process.env.SOCIOTECHNIC_DESIGN_RECEIPT, JSON.stringify({ contextLoaded: true, dispatch, fake: true }));
  write(JSON.stringify(packet, null, 2));
} else if (agent === "sociotechnic-researcher") {
  write("STATUS: DONE\n\n## Answer\n\nNothing to research.\n\n## Evidence\n\n- README.md:1\n");
} else if (agent === "sociotechnic-builder" || agent === "sociotechnic-builder-lite" || agent === "sociotechnic-sweeper") {
  mkdirSync(join(worktree, "src"), { recursive: true });
  writeFileSync(join(worktree, "src", "feature.txt"), `round ${round} dispatch ${dispatch}\n`);
  git("add", "-A");
  git("commit", "-q", "-m", `build round ${round}`);
  const head = git("rev-parse", "HEAD");
  write(
    `STATUS: READY\nCOMMIT: ${head}\n\n## Summary\n\nWrote the feature file.\n\n## Acceptance\n\n- [x] src/feature.txt exists — checked with ls\n\n## Deviations\n\n- none\n\n## Notes for reviewers\n\nNothing special.\n`,
  );
} else if (agent === "sociotechnic-approver") {
  const head = git("rev-parse", "HEAD");
  write(`DECISION: APPROVE\nCOMMIT: ${head}\n\n## Reasons\n\n- every acceptance criterion has evidence\n`);
} else if (agent.startsWith("sociotechnic-reviewer-") || agent === "sociotechnic-conformance") {
  const head = git("rev-parse", "HEAD");
  const steps = agent === "sociotechnic-conformance" ? "\n## Plan steps\n\n| stage | status | justification |\n| --- | --- | --- |\n| s1 | implemented | |\n" : "";
  write(`VERDICT: PASS\nCOMMIT: ${head}\n\n## Findings\n\nNone.\n${steps}\n## Notes\n\nReviewed by the fake agent.\n`);
} else {
  process.stderr.write(`fake-agent: unexpected agent ${agent}\n`);
  process.exit(2);
}
